#endif /* ARCH_X86 || ARCH_X86_64 */

#if defined(ACCEL_DETECT) && (defined(ARCH_PPC) || defined(ARCH_SPARC))
#include <signal.h>
#include <setjmp.h>

static sigjmp_buf jmpbuf;
static volatile sig_atomic_t canjump = 0;

static RETSIGTYPE sigill_handler (int sig)
{
    if (!canjump) {
	signal (sig, SIG_DFL);
	raise (sig);
    }

    canjump = 0;
    siglongjmp (jmpbuf, 1);
}
#endif /* ACCEL_DETECT && (ARCH_PPC || ARCH_SPARC) */

#ifdef ARCH_PPC
static uint32_t arch_accel (uint32_t accel)
{
#ifdef ACCEL_DETECT
    if ((accel & (MPEG2_ACCEL_PPC_ALTIVEC | MPEG2_ACCEL_DETECT)) ==
	MPEG2_ACCEL_DETECT) {
	static RETSIGTYPE (* oldsig) (int);

	oldsig = signal (SIGILL, sigill_handler);
	if (sigsetjmp (jmpbuf, 1)) {
	    signal (SIGILL, oldsig);
	    return accel;
	}

	canjump = 1;

#if defined(__APPLE_CC__)	/* apple */
#define VAND(a,b,c) "vand v" #a ",v" #b ",v" #c "\n\t"
#else				/* gnu */
#define VAND(a,b,c) "vand " #a "," #b "," #c "\n\t"
#endif
	asm volatile ("mtspr 256, %0\n\t"
		      VAND (0, 0, 0)
		      :
		      : "r" (-1));

	canjump = 0;
	accel |= MPEG2_ACCEL_PPC_ALTIVEC;

	signal (SIGILL, oldsig);
    }
#endif /* ACCEL_DETECT */

    return accel;
}
#endif /* ARCH_PPC */

#ifdef ARCH_SPARC
static uint32_t arch_accel (uint32_t accel)
{
    if (accel & MPEG2_ACCEL_SPARC_VIS2)
	accel |= MPEG2_ACCEL_SPARC_VIS;

#ifdef ACCEL_DETECT
    if ((accel & (MPEG2_ACCEL_SPARC_VIS2 | MPEG2_ACCEL_DETECT)) ==
	MPEG2_ACCEL_DETECT) {
	static RETSIGTYPE (* oldsig) (int);

	oldsig = signal (SIGILL, sigill_handler);
	if (sigsetjmp (jmpbuf, 1)) {
	    signal (SIGILL, oldsig);
	    return accel;
	}

	canjump = 1;

	/* pdist %f0, %f0, %f0 */
	__asm__ __volatile__(".word\t0x81b007c0");

	canjump = 0;
	accel |= MPEG2_ACCEL_SPARC_VIS;

	if (sigsetjmp (jmpbuf, 1)) {
	    signal (SIGILL, oldsig);
	    return accel;
	}

	canjump = 1;

	/* edge8n %g0, %g0, %g0 */
	__asm__ __volatile__(".word\t0x81b00020");

	canjump = 0;
	accel |= MPEG2_ACCEL_SPARC_VIS2;

	signal (SIGILL, oldsig);
    }
#endif /* ACCEL_DETECT */

    return accel;
}
#endif /* ARCH_SPARC */

#ifdef ARCH_ALPHA
static inline uint32_t arch_accel (uint32_t accel)
{
    if (accel & MPEG2_ACCEL_ALPHA_MVI)
	accel |= MPEG2_ACCEL_ALPHA;

#ifdef ACCEL_DETECT
    if (accel & MPEG2_ACCEL_DETECT) {
	uint64_t no_mvi;

	asm volatile ("amask %1, %0"
		      : "=r" (no_mvi)
		      : "rI" (256));	/* AMASK_MVI */
	accel |= no_mvi ? MPEG2_ACCEL_ALPHA : (MPEG2_ACCEL_ALPHA |
					       MPEG2_ACCEL_ALPHA_MVI);
    }
#endif /* ACCEL_DETECT */

    return accel;
}
#endif /* ARCH_ALPHA */

uint32_t mpeg2_detect_accel (uint32_t accel)
{
#if defined (ARCH_X86) || defined (ARCH_X86_64) || defined (ARCH_PPC) || defined (ARCH_ALPHA) || defined (ARCH_SPARC)
    accel = arch_accel (accel);
#endif
    return accel;
