449: static int xv_alloc_frames (x11_instance_t * instance, int size,
450: 			    int fourcc)
451: {
452:     char * alloc;
453:     int i = 0;
454: 
455:     instance->xshm = 1;
456:     alloc = instance->xshm_extension  ?
457: 	(char *) create_shm (instance, 3 * size) : NULL;
458:     if (alloc == NULL) {
459: 	instance->xshm = 0;
460: 	alloc = (char *) malloc (3 * size);
461: 	if (alloc == NULL)
462: 	    return 1;
463:     }
464: 
465:     while (i < 3) {
466: 	instance->frame[i].wait_completion = 0;
467: 	instance->frame[i].xvimage = instance->xshm ?
468: 	    XvShmCreateImage (instance->display, instance->port, fourcc,
469: 			      alloc, instance->width, instance->height,
470: 			      &(instance->shminfo)) :
471: 	    XvCreateImage (instance->display, instance->port, fourcc,
472: 			   alloc, instance->width, instance->height);
473: 	instance->frame[i].data = alloc;
474: 	alloc += size;
475: 	if ((instance->frame[i].xvimage == NULL) ||
476: 	    (instance->frame[i++].xvimage->data_size != size)) {
477: 	    while (--i >= 0)
478: 		XFree (instance->frame[i].xvimage);
479: 	    if (instance->xshm)
480: 		destroy_shm (instance);
481: 	    else
482: 		free (instance->frame[0].data);
483: 	    return 1;
484: 	}
485:     }
486: 
487:     return 0;
