85: static long FAR PASCAL event_procedure (HWND hwnd, UINT message,
86: 					WPARAM wParam, LPARAM lParam)
87: {
88:     RECT rect_window;
89:     POINT point_window;
90:     dx_instance_t * instance;
91: 
92:     switch (message) {
93: 
94:     case WM_WINDOWPOSCHANGED:
95: 	instance = (dx_instance_t *) GetWindowLong (hwnd, GWL_USERDATA);
96: 
97: 	/* update the window position and size */
98: 	point_window.x = 0;
99: 	point_window.y = 0;
100: 	ClientToScreen (hwnd, &point_window);
101: 	instance->window_coords.left = point_window.x;
102: 	instance->window_coords.top = point_window.y;
103: 	GetClientRect (hwnd, &rect_window);
104: 	instance->window_coords.right = rect_window.right + point_window.x;
105: 	instance->window_coords.bottom = rect_window.bottom + point_window.y;
106: 
107: 	/* update the overlay */
108: 	if (instance->overlay && instance->display)
109: 	    update_overlay (instance);
110: 
111: 	return 0;
112: 
113:     case WM_CLOSE:	/* forbid the user to close the window */
114: 	return 0;
115: 
116:     case WM_DESTROY:	/* just destroy the window */
117: 	PostQuitMessage (0);
118: 	return 0;
119:     }
120: 
121:     return DefWindowProc (hwnd, message, wParam, lParam);
122: }
