443: static void copy_yuv_picture (dx_instance_t * instance,
444: 			      uint8_t * const * buf, void * id)
445: {
446:     uint8_t * dest[3];
447:     int width, i;
448: 
449:     dest[0] = instance->yuv[0];
450:     dest[1] = instance->yuv[1];
451:     dest[2] = instance->yuv[2];
452: 
453:     width = instance->width;
454:     for (i = 0; i < instance->height >> 1; i++) {
455: 	memcpy (dest[0], buf[0] + 2 * i * width, width);
456: 	dest[0] += instance->stride;
457: 	memcpy (dest[0], buf[0] + (2 * i + 1) * width, width);
458: 	dest[0] += instance->stride;
459: 	memcpy (dest[1], buf[1] + i * (width >> 1), width >> 1);
460: 	dest[1] += instance->stride >> 1;
461: 	memcpy (dest[2], buf[2] + i * (width >> 1), width >> 1);
462: 	dest[2] += instance->stride >> 1;
463:     }
464: }
