88: 
89:     elapsed = (tv_end.tv_sec - tv_beg.tv_sec) * 100 +
90: 	(tv_end.tv_usec - tv_beg.tv_usec) / 10000;
91:     total_elapsed = (tv_end.tv_sec - tv_start.tv_sec) * 100 +
92: 	(tv_end.tv_usec - tv_start.tv_usec) / 10000;
93: 
94:     if (final) {
95: 	if (total_elapsed)
96: 	    tfps = frame_counter * 100.0 / total_elapsed;
97: 	else
98: 	    tfps = 0;
99: 
100: 	fprintf (stderr,"\n%d frames decoded in %.2f seconds (%.2f fps)\n",
101: 		 frame_counter, total_elapsed / 100.0, tfps);
102: 
103: 	return;
104:     }
105: 
106:     frame_counter++;
107: 
108:     if (elapsed < 50)	/* only display every 0.50 seconds */
109: 	return;
110: 
111:     tv_beg = tv_end;
112:     frames = frame_counter - last_count;
113: 
114:     fps = frames * 100.0 / elapsed;
115:     tfps = frame_counter * 100.0 / total_elapsed;
116: 
117:     fprintf (stderr, "%d frames in %.2f sec (%.2f fps), "
118: 	     "%d last %.2f sec (%.2f fps)\033[K\r", frame_counter,
119: 	     total_elapsed / 100.0, tfps, frames, elapsed / 100.0, fps);
120: 
121:     last_count = frame_counter;
