260:         return NULL;
261:     }
262:     buf = mpeg2_malloc (size, (mpeg2_alloc_t)-1);
263:     if (buf && (reason == MPEG2_ALLOC_YUV || reason == MPEG2_ALLOC_CONVERTED))
264:         memset (buf, 0, size);
