591: static void ps_loop (void)
592: {
593:     uint8_t * buffer = (uint8_t *) malloc (buffer_size);
594:     uint8_t * end;
595: 
596:     if (buffer == NULL)
597: 	exit (1);
598:     do {
599: 	end = buffer + fread (buffer, 1, buffer_size, in_file);
600: 	if (demux (buffer, end, 0))
601: 	    break;	/* hit program_end_code */
602:     } while (end == buffer + buffer_size && !sigint);
603:     free (buffer);
604: }
