606: static int pva_demux (uint8_t * buf, uint8_t * end)
607: {
608:     static int state = DEMUX_SKIP;
609:     static int state_bytes = 0;
610:     static uint8_t head_buf[15];
611: 
612:     uint8_t * header;
613:     int bytes;
614:     int len;
615: 
616:     switch (state) {
617:     case DEMUX_HEADER:
618:         if (state_bytes > 0) {
619:             header = head_buf;
620:             bytes = state_bytes;
621:             goto continue_header;
622:         }
623:         break;
624:     case DEMUX_DATA:
625:         if (state_bytes > end - buf) {
626:             decode_mpeg2 (buf, end);
627:             state_bytes -= end - buf;
628:             return 0;
629:         }
630:         decode_mpeg2 (buf, buf + state_bytes);
631:         buf += state_bytes;
632:         break;
633:     case DEMUX_SKIP:
634:         if (state_bytes > end - buf) {
635:             state_bytes -= end - buf;
636:             return 0;
637:         }
638:         buf += state_bytes;
639:         break;
640:     }
641: 
642:     while (1) {
643:     payload_start:
644: 	header = buf;
645: 	bytes = end - buf;
646:     continue_header:
647: 	NEEDBYTES (2);
648: 	if (header[0] != 0x41 || header[1] != 0x56) {
649: 	    if (header != head_buf) {
650: 		buf++;
651: 		goto payload_start;
652: 	    } else {
653: 		header[0] = header[1];
654: 		bytes = 1;
655: 		goto continue_header;
656: 	    }
657: 	}
658: 	NEEDBYTES (8);
659: 	if (header[2] != 1) {
660: 	    DONEBYTES (8);
661: 	    bytes = (header[6] << 8) + header[7];
662: 	    if (bytes > end - buf) {
663: 		state = DEMUX_SKIP;
664: 		state_bytes = bytes - (end - buf);
665: 		return 0;
666: 	    } 
667: 	    buf += bytes; 
668: 	} else {
669: 	    len = 8;
670: 	    if (header[5] & 0x10) {
671: 		len = 12 + (header[5] & 3);
672: 		NEEDBYTES (len);
673: 		decode_mpeg2 (header + 12, header + len);
674: 		mpeg2_tag_picture (mpeg2dec,
675: 				   ((header[8] << 24) | (header[9] << 16) |
676: 				    (header[10] << 8) | header[11]), 0);
677: 	    }
678: 	    DONEBYTES (len);
679: 	    bytes = (header[6] << 8) + header[7] + 8 - len;
680: 	    if (bytes > end - buf) {
681: 		decode_mpeg2 (buf, end);
682: 		state = DEMUX_DATA;
683: 		state_bytes = bytes - (end - buf);
684: 		return 0;
685: 	    } else if (bytes > 0) {
686: 		decode_mpeg2 (buf, buf + bytes);
687: 		buf += bytes;
688: 	    }
689: 	}
690:     }
691: }
