693: static void pva_loop (void)
694: {
695:     uint8_t * buffer = (uint8_t *) malloc (buffer_size);
696:     uint8_t * end;
697: 
698:     if (buffer == NULL)
699: 	exit (1);
700:     do {
701: 	end = buffer + fread (buffer, 1, buffer_size, in_file);
702: 	pva_demux (buffer, end);
703:     } while (end == buffer + buffer_size && !sigint);
704:     free (buffer);
705: }
