707: static void ts_loop (void)
708: {
709:     uint8_t * buffer = (uint8_t *) malloc (buffer_size);
710:     uint8_t * buf;
711:     uint8_t * nextbuf;
712:     uint8_t * data;
713:     uint8_t * end;
714:     int pid;
715: 
716:     if (buffer == NULL || buffer_size < 188)
717: 	exit (1);
718:     buf = buffer;
719:     do {
720: 	end = buf + fread (buf, 1, buffer + buffer_size - buf, in_file);
721: 	buf = buffer;
722: 	for (; (nextbuf = buf + 188) <= end; buf = nextbuf) {
723: 	    if (*buf != 0x47) {
724: 		fprintf (stderr, "bad sync byte\n");
725: 		nextbuf = buf + 1;
726: 		continue;
727: 	    }
728: 	    pid = ((buf[1] << 8) + buf[2]) & 0x1fff;
729: 	    if (pid != demux_pid)
730: 		continue;
731: 	    data = buf + 4;
732: 	    if (buf[3] & 0x20) {	/* buf contains an adaptation field */
733: 		data = buf + 5 + buf[4];
734: 		if (data > nextbuf)
735: 		    continue;
736: 	    }
737: 	    if (buf[3] & 0x10)
738: 		demux (data, nextbuf,
739: 		       (buf[1] & 0x40) ? DEMUX_PAYLOAD_START : 0);
740: 	}
741: 	if (end != buffer + buffer_size)
742: 	    break;
743: 	memcpy (buffer, buf, end - buf);
744: 	buf = buffer + (end - buf);
745:     } while (!sigint);
746:     free (buffer);
747: }
