749: static void es_loop (void)
750: {
751:     uint8_t * buffer = (uint8_t *) malloc (buffer_size);
752:     uint8_t * end;
753: 
754:     if (buffer == NULL)
755: 	exit (1);
756:     do {
757: 	end = buffer + fread (buffer, 1, buffer_size, in_file);
758: 	decode_mpeg2 (buffer, end);
759:     } while (end == buffer + buffer_size && !sigint);
760:     free (buffer);
761: }
