764: {
765: #ifdef HAVE_IO_H
766:     setmode (fileno (stdin), O_BINARY);
767:     setmode (fileno (stdout), O_BINARY);
768: #endif
769: 
770:     fprintf (stderr, PACKAGE"-"VERSION
771: 	     " - by Michel Lespinasse <walken@zoy.org> and Aaron Holtzman\n");
