773:     handle_args (argc, argv);
774: 
775:     output = output_open ();
776:     if (output == NULL) {
777: 	fprintf (stderr, "Can not open output\n");
778: 	return 1;
779:     }
780:     mpeg2dec = mpeg2_init ();
781:     if (mpeg2dec == NULL)
782: 	exit (1);
783:     mpeg2_malloc_hooks (malloc_hook, NULL);
784: 
785:     if (demux_pva)
786: 	pva_loop ();
787:     else if (demux_pid)
788: 	ts_loop ();
789:     else if (demux_track)
790: 	ps_loop ();
791:     else
792: 	es_loop ();
793: 
794:     mpeg2_close (mpeg2dec);
795:     if (output->close)
796: 	output->close (output);
797:     print_fps (1);
798:     fclose (in_file);
799:     return 0;
